"use client";
import React from "react";
import "@copilotkit/react-core/v2/styles.css";
import "./style.css";
import {
  CopilotChat,
  useConfigureSuggestions,
} from "@copilotkit/react-core/v2";
import { CopilotKit } from "@copilotkit/react-core";
import { fixedSchemaCatalog } from "@/a2ui-catalog";

export const dynamic = "force-dynamic";

interface PageProps {
  params: Promise<{ integrationId: string }>;
}

function Chat() {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Search flights",
        message: "Find flights from SFO to JFK for next Tuesday.",
      },
      {
        title: "Search hotels",
        message: "Find hotels in downtown Manhattan for next weekend.",
      },
    ],
    available: "always",
  });

  return (
    <CopilotChat
      agentId="a2ui_fixed_schema"
      className="h-full rounded-2xl max-w-6xl mx-auto"
    />
  );
}

export default function Page({ params }: PageProps) {
  const { integrationId } = React.use(params);

  return (
    <CopilotKit
      runtimeUrl={`/api/copilotkit/${integrationId}`}
      showDevConsole={false}
      agent="a2ui_fixed_schema"
      a2ui={{ catalog: fixedSchemaCatalog }}
    >
      <div className="flex justify-center items-center h-full w-full">
        <div className="h-full w-full md:w-8/10 md:h-8/10 rounded-lg">
          <Chat />
        </div>
      </div>
    </CopilotKit>
  );
}

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400&display=swap');

.a2ui-surface {
  --primary: #111111;
  --primary-foreground: #ffffff;
  --card: #ffffff;
  --border: #e0e0e0;
  --radius: 12px;
  --foreground: #111111;
  --input: #d4d4d4;
  --background: #fafafa;

  font-family: "Plus Jakarta Sans", -apple-system, BlinkMacSystemFont, system-ui, sans-serif !important;
  letter-spacing: -0.01em;
}

/* Constrain images to consistent sizes */
.a2ui-surface img {
  max-width: 28px;
  max-height: 28px;
  border-radius: 4px;
}

/* Status dot should be even smaller */
.a2ui-surface img[alt="On Time"],
.a2ui-surface img[alt="Delayed"],
.a2ui-surface img[alt="Cancelled"] {
  max-width: 10px;
  max-height: 10px;
  border-radius: 50%;
}

/* Consistent card width so single-card streaming doesn't collapse narrow */
.a2ui-surface .a2ui-card {
  min-width: 280px;
}

