"use client";
import React, { useState, useEffect } from "react";
import "@copilotkit/react-core/v2/styles.css";
import { 
  useHumanInTheLoop,
  useConfigureSuggestions,
  CopilotChat,
  CopilotChatConfigurationProvider,
} from "@copilotkit/react-core/v2";
import { CopilotKit,
useLangGraphInterrupt } from "@copilotkit/react-core";
import { z } from "zod";
import { useTheme } from "next-themes";

interface HumanInTheLoopProps {
  params: Promise<{
    integrationId: string;
  }>;
}

const HumanInTheLoop: React.FC<HumanInTheLoopProps> = ({ params }) => {
  const { integrationId } = React.use(params);

  return (
    <CopilotKit
      runtimeUrl={`/api/copilotkit/${integrationId}`}
      showDevConsole={false}
      agent="human_in_the_loop"
    >
      <Chat integrationId={integrationId} />
    </CopilotKit>
  );
};

interface Step {
  description: string;
  status: "disabled" | "enabled" | "executing";
}

// Shared UI Components
const StepContainer = ({ theme, children }: { theme?: string; children: React.ReactNode }) => (
  <div data-testid="select-steps" className="flex">
    <div
      className={`relative rounded-xl w-[600px] p-6 shadow-lg backdrop-blur-sm ${
        theme === "dark"
          ? "bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 text-white border border-slate-700/50 shadow-2xl"
          : "bg-gradient-to-br from-white via-gray-50 to-white text-gray-800 border border-gray-200/80"
      }`}
    >
      {children}
    </div>
  </div>
);

const StepHeader = ({
  theme,
  enabledCount,
  totalCount,
  status,
  showStatus = false,
}: {
  theme?: string;
  enabledCount: number;
  totalCount: number;
  status?: string;
  showStatus?: boolean;
}) => (
  <div className="mb-5">
    <div className="flex items-center justify-between mb-3">
      <h2 className="text-xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
        Select Steps
      </h2>
      <div className="flex items-center gap-3">
        <div className={`text-sm ${theme === "dark" ? "text-slate-400" : "text-gray-500"}`}>
          {enabledCount}/{totalCount} Selected
        </div>
        {showStatus && (
          <div
            className={`text-xs px-2 py-1 rounded-full font-medium ${
              status === "executing"
                ? theme === "dark"
                  ? "bg-blue-900/30 text-blue-300 border border-blue-500/30"
                  : "bg-blue-50 text-blue-600 border border-blue-200"
                : theme === "dark"
                  ? "bg-slate-700 text-slate-300"
                  : "bg-gray-100 text-gray-600"
            }`}
          >
            {status === "executing" ? "Ready" : "Waiting"}
          </div>
        )}
      </div>
    </div>

    <div
      className={`relative h-2 rounded-full overflow-hidden ${theme === "dark" ? "bg-slate-700" : "bg-gray-200"}`}
    >
      <div
        className="absolute top-0 left-0 h-full bg-gradient-to-r from-blue-500 to-purple-500 rounded-full transition-all duration-500 ease-out"
        style={{ width: `${totalCount > 0 ? (enabledCount / totalCount) * 100 : 0}%` }}
      />
    </div>
  </div>
);

const StepItem = ({
  step,
  theme,
  status,
  onToggle,
  disabled = false,
}: {
  step: { description: string; status: string };
  theme?: string;
  status?: string;
  onToggle: () => void;
  disabled?: boolean;
}) => (
  <div
    className={`flex items-center p-3 rounded-lg transition-all duration-300 ${
      step.status === "enabled"
        ? theme === "dark"
          ? "bg-gradient-to-r from-blue-900/20 to-purple-900/10 border border-blue-500/30"
          : "bg-gradient-to-r from-blue-50 to-purple-50 border border-blue-200/60"
        : theme === "dark"
          ? "bg-slate-800/30 border border-slate-600/30"
          : "bg-gray-50/50 border border-gray-200/40"
    }`}
  >
    <label data-testid="step-item" className="flex items-center cursor-pointer w-full">
      <div className="relative">
        <input
          type="checkbox"
          checked={step.status === "enabled"}
          onChange={onToggle}
          className="sr-only"
          disabled={disabled}
        />
        <div
          className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all duration-200 ${
            step.status === "enabled"
              ? "bg-gradient-to-br from-blue-500 to-purple-600 border-blue-500"
              : theme === "dark"
                ? "border-slate-400 bg-slate-700"
                : "border-gray-300 bg-white"
          } ${disabled ? "opacity-60" : ""}`}
        >
          {step.status === "enabled" && (
            <svg
              className="w-3 h-3 text-white"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={3}
                d="M5 13l4 4L19 7"
              />
            </svg>
          )}
        </div>
      </div>
      <span
        data-testid="step-text"
        className={`ml-3 font-medium transition-all duration-300 ${
          step.status !== "enabled" && status != "inProgress"
            ? `line-through ${theme === "dark" ? "text-slate-500" : "text-gray-400"}`
            : theme === "dark"
              ? "text-white"
              : "text-gray-800"
        } ${disabled ? "opacity-60" : ""}`}
      >
        {step.description}
      </span>
    </label>
  </div>
);

const ActionButton = ({
  variant,
  theme,
  disabled,
  onClick,
  children,
}: {
  variant: "primary" | "secondary" | "success" | "danger";
  theme?: string;
  disabled?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) => {
  const baseClasses = "px-6 py-3 rounded-lg font-semibold transition-all duration-200";
  const enabledClasses = "hover:scale-105 shadow-md hover:shadow-lg";
  const disabledClasses = "opacity-50 cursor-not-allowed";

  const variantClasses = {
    primary:
      "bg-gradient-to-r from-purple-500 to-purple-700 hover:from-purple-600 hover:to-purple-800 text-white shadow-lg hover:shadow-xl",
    secondary:
      theme === "dark"
        ? "bg-slate-700 hover:bg-slate-600 text-white border border-slate-600 hover:border-slate-500"
        : "bg-gray-100 hover:bg-gray-200 text-gray-800 border border-gray-300 hover:border-gray-400",
    success:
      "bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 text-white shadow-lg hover:shadow-xl",
    danger:
      "bg-gradient-to-r from-red-500 to-red-600 hover:from-red-600 hover:to-red-700 text-white shadow-lg hover:shadow-xl",
  };

  return (
    <button
      className={`${baseClasses} ${disabled ? disabledClasses : enabledClasses} ${
        disabled && variant === "secondary"
          ? "bg-gray-200 text-gray-500"
          : disabled && variant === "success"
            ? "bg-gray-400"
            : variantClasses[variant]
      }`}
      disabled={disabled}
      onClick={onClick}
    >
      {children}
    </button>
  );
};

const DecorativeElements = ({
  theme,
  variant = "default",
}: {
  theme?: string;
  variant?: "default" | "success" | "danger";
}) => (
  <>
    <div
      className={`absolute top-3 right-3 w-16 h-16 rounded-full blur-xl ${
        variant === "success"
          ? theme === "dark"
            ? "bg-gradient-to-br from-green-500/10 to-emerald-500/10"
            : "bg-gradient-to-br from-green-200/30 to-emerald-200/30"
          : variant === "danger"
            ? theme === "dark"
              ? "bg-gradient-to-br from-red-500/10 to-pink-500/10"
              : "bg-gradient-to-br from-red-200/30 to-pink-200/30"
            : theme === "dark"
              ? "bg-gradient-to-br from-blue-500/10 to-purple-500/10"
              : "bg-gradient-to-br from-blue-200/30 to-purple-200/30"
      }`}
    />
    <div
      className={`absolute bottom-3 left-3 w-12 h-12 rounded-full blur-xl ${
        variant === "default"
          ? theme === "dark"
            ? "bg-gradient-to-br from-purple-500/10 to-pink-500/10"
            : "bg-gradient-to-br from-purple-200/30 to-pink-200/30"
          : "opacity-50"
      }`}
    />
  </>
);
const InterruptHumanInTheLoop: React.FC<{
  event: { value: { steps: Step[] } };
  resolve: (value: string) => void;
}> = ({ event, resolve }) => {
  const { theme } = useTheme();

  // Parse and initialize steps data
  let initialSteps: Step[] = [];
  if (event.value && event.value.steps && Array.isArray(event.value.steps)) {
    initialSteps = event.value.steps.map((step: Step | string) => ({
      description: typeof step === "string" ? step : step.description || "",
      status: typeof step === "object" && step.status ? step.status : "enabled",
    }));
  }

  const [localSteps, setLocalSteps] = useState<Step[]>(initialSteps);
  const enabledCount = localSteps.filter((step) => step.status === "enabled").length;

  const handleStepToggle = (index: number) => {
    setLocalSteps((prevSteps) =>
      prevSteps.map((step, i) =>
        i === index
          ? { ...step, status: step.status === "enabled" ? "disabled" : "enabled" }
          : step,
      ),
    );
  };

  const handlePerformSteps = () => {
    const selectedSteps = localSteps
      .filter((step) => step.status === "enabled")
      .map((step) => step.description);
    resolve("The user selected the following steps: " + selectedSteps.join(", "));
  };

  return (
    <StepContainer theme={theme}>
      <StepHeader theme={theme} enabledCount={enabledCount} totalCount={localSteps.length} />

      <div className="space-y-3 mb-6">
        {localSteps.map((step, index) => (
          <StepItem
            key={index}
            step={step}
            theme={theme}
            onToggle={() => handleStepToggle(index)}
          />
        ))}
      </div>

      <div className="flex justify-center">
        <ActionButton variant="primary" theme={theme} onClick={handlePerformSteps}>
          <span className="text-lg">✨</span>
          Perform Steps
          <span
            className={`ml-1 px-2 py-1 rounded-full text-xs font-bold ${
              theme === "dark" ? "bg-purple-800/50" : "bg-purple-600/20"
            }`}
          >
            {enabledCount}
          </span>
        </ActionButton>
      </div>

      <DecorativeElements theme={theme} />
    </StepContainer>
  );
};

const Chat = ({ integrationId }: { integrationId: string }) => {
  return (
    <CopilotChatConfigurationProvider agentId="human_in_the_loop">
      <ChatContent />
    </CopilotChatConfigurationProvider>
  );
};

const ChatContent = () => {
  useConfigureSuggestions({
    suggestions: [
      { title: "Simple plan", message: "Please plan a trip to mars in 5 steps." },
      { title: "Complex plan", message: "Please plan a pasta dish in 10 steps." },
    ],
    available: "always",
  });

  // Langgraph uses it's own hook to handle human-in-the-loop interactions via langgraph interrupts,
  // This hook won't do anything for other integrations.
  useLangGraphInterrupt({

    render: ({ event, resolve }) => <InterruptHumanInTheLoop event={event} resolve={resolve} />,
  });
  useHumanInTheLoop<{ steps: Step[] }>({
    agentId: "human_in_the_loop",
    name: "generate_task_steps",
    description: "Generates a list of steps for the user to perform",
     parameters: z.object({
      steps: z.array(
        z.object({
          description: z.string(),
          status: z.enum(["enabled", "disabled", "executing"]),
        }),
      ),
    })  ,
    // Note: In v1, `available` was used to disable this for langgraph integrations.
    // In v2, availability is handled at the agent/backend level.
    render: ({ args, respond, status }) => {
      return <StepsFeedback args={args} respond={respond} status={status} />;
    },
  });

  return (
    <div className="flex justify-center items-center h-full w-full">
      <div className="h-full w-full md:w-8/10 md:h-8/10 rounded-lg">
        <CopilotChat
          agentId="human_in_the_loop"
          className="h-full rounded-2xl max-w-6xl mx-auto"
        />
      </div>
    </div>
  );
};

interface StepsFeedbackProps {
  args: { steps?: Step[] };
  respond?: (result: unknown) => Promise<void>;
  status: string;
}

const StepsFeedback = ({ args, respond, status }: StepsFeedbackProps) => {
  const { theme } = useTheme();
  const [localSteps, setLocalSteps] = useState<Step[]>([]);
  const [accepted, setAccepted] = useState<boolean | null>(null);

  // NOTE (PNI-272): kept as an effect. Snapshotting during render would
  // populate `localSteps` before the first commit, which is a behaviour change.
  useEffect(() => {
    if (status === "executing" && localSteps.length === 0 && Array.isArray(args?.steps) && args.steps.length > 0) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setLocalSteps(args.steps);
    }
  }, [status, args?.steps, localSteps]);

  if (!Array.isArray(args?.steps) || args.steps.length === 0) {
    return <></>;
  }

  const steps = Array.isArray(localSteps) && localSteps.length > 0 ? localSteps : args.steps;
  const enabledCount = steps.filter((step: Step) => step.status === "enabled").length;

  const handleStepToggle = (index: number) => {
    setLocalSteps((prevSteps) =>
      prevSteps.map((step, i) =>
        i === index
          ? { ...step, status: step.status === "enabled" ? "disabled" : "enabled" }
          : step,
      ),
    );
  };

  const handleReject = () => {
    if (respond) {
      setAccepted(false);
      respond({ accepted: false });
    }
  };

  const handleConfirm = () => {
    if (respond) {
      const confirmedSteps = localSteps.filter((step) => step.status === "enabled");
      setAccepted(true);
      respond({ accepted: true, steps: confirmedSteps });
    }
  };

  return (
    <StepContainer theme={theme}>
      <StepHeader
        theme={theme}
        enabledCount={enabledCount}
        totalCount={steps.length}
        status={status}
        showStatus={true}
      />

      <div className="space-y-3 mb-6">
        {steps.map((step: Step, index: number) => (
          <StepItem
            key={index}
            step={step}
            theme={theme}
            status={status}
            onToggle={() => handleStepToggle(index)}
            disabled={status !== "executing"}
          />
        ))}
      </div>

      {/* Action Buttons - Different logic from InterruptHumanInTheLoop */}
      {accepted === null && (
        <div className="flex justify-center gap-4">
          <ActionButton
            variant="secondary"
            theme={theme}
            disabled={status !== "executing"}
            onClick={handleReject}
          >
            <span className="mr-2">✗</span>
            Reject
          </ActionButton>
          <ActionButton
            variant="success"
            theme={theme}
            disabled={status !== "executing"}
            onClick={handleConfirm}
          >
            <span className="mr-2">✓</span>
            Confirm
            <span
              className={`ml-2 px-2 py-1 rounded-full text-xs font-bold ${
                theme === "dark" ? "bg-green-800/50" : "bg-green-600/20"
              }`}
            >
              {enabledCount}
            </span>
          </ActionButton>
        </div>
      )}

      {/* Result State - Unique to StepsFeedback */}
      {accepted !== null && (
        <div className="flex justify-center">
          <div
            className={`px-6 py-3 rounded-lg font-semibold flex items-center gap-2 ${
              accepted
                ? theme === "dark"
                  ? "bg-green-900/30 text-green-300 border border-green-500/30"
                  : "bg-green-50 text-green-700 border border-green-200"
                : theme === "dark"
                  ? "bg-red-900/30 text-red-300 border border-red-500/30"
                  : "bg-red-50 text-red-700 border border-red-200"
            }`}
          >
            <span className="text-lg">{accepted ? "✓" : "✗"}</span>
            {accepted ? "Accepted" : "Rejected"}
          </div>
        </div>
      )}

      <DecorativeElements
        theme={theme}
        variant={accepted === true ? "success" : accepted === false ? "danger" : "default"}
      />
    </StepContainer>
  );
};

export default HumanInTheLoop;

/**
 * Human-in-the-Loop example for AWS Strands (TypeScript).
 *
 * The `generate_task_steps` tool is declared on the frontend via
 * `useHumanInTheLoop`. The @ag-ui/aws-strands adapter auto-registers it as a
 * proxy tool when `RunAgentInput.tools` arrives, so the backend does not
 * register a native tool here — Strands invokes the proxy, the adapter halts
 * the run after the proxy returns, the user reviews and approves the plan in
 * the UI, and the tool result is fed back to the agent on the next turn.
 *
 * No backend tool stub. No agent-side AG-UI event emission.
 */

import { Agent } from "@strands-agents/sdk";
import { StrandsAgent } from "@ag-ui/aws-strands";
import { createStrandsApp } from "@ag-ui/aws-strands/server";
import { createModel } from "../model-factory";
import { demoPort, listenOrExit, runIfMain } from "../run-if-main";

// Steps 4-6 and the third "Important" bullet describe the payload the dojo page
// sends back. Accepting posts `{ accepted: true, steps }` with the disabled
// steps removed rather than flagged; rejecting posts `{ accepted: false }` and
// nothing else. Without this the model narrates its own original list and the
// card's approvals read as ignored.
export const SYSTEM_PROMPT = `You are a task planning assistant specialized in creating clear, actionable step-by-step plans.

**Your Primary Role:**
- Break down any user request into exactly 10 clear, actionable steps
- Generate steps that require human review and approval
- Execute only human-approved steps

**When a user requests help with a task:**
1. ALWAYS use the \`generate_task_steps\` tool to create a breakdown (default to 10 steps unless told otherwise)
2. Each step must be:
   - Brief (only a few words)
   - In imperative form (e.g., "Dig hole", "Open door", "Mix ingredients")
   - Clear and actionable
   - Logically ordered from start to finish
3. Set all steps to "enabled" status initially
4. After the user reviews the plan, the \`generate_task_steps\` tool result will arrive as JSON. It always
   carries \`"accepted": <bool>\`. When accepted it also carries \`"steps": [...]\`, containing ONLY the steps the
   user approved — disabled steps are removed entirely. When rejected there is no \`steps\` key at all.
5. Treat that \`steps\` array as the SINGLE SOURCE OF TRUTH for what was approved. Do NOT fall back to the original tool arguments.
   - If accepted: briefly confirm the plan (only include the approved steps from the tool result) and proceed (don't repeat the full original list). Do not ask for more clarifying information.
   - If rejected: Ask what they'd like to change (don't call \`generate_task_steps\` again until they provide input)
6. When the user accepts the plan, "execute" the plan by repeating ONLY the approved steps (those present in the tool result's \`steps\` array) in order as if you have just done them. Then let the user know you have completed the plan.
    - example: if the tool result steps are "Dig hole", "Open door", "Mix ingredients", you would respond with "Digging hole... Opening door... Mixing ingredients..."

**Important:**
- NEVER call \`generate_task_steps\` twice in a row without user input
- NEVER repeat the list of steps in your response after calling the tool
- NEVER mention or execute steps that are absent from the tool result's \`steps\` array
- DO provide a brief, creative summary of how you would execute the approved steps
- For follow-up questions about a previously executed plan, just answer in plain text — do NOT invoke any tool
`;

export async function createHumanInTheLoopAgent(): Promise<StrandsAgent> {
  return new StrandsAgent({
    agent: new Agent({
      model: await createModel(),
      tools: [],
      systemPrompt: SYSTEM_PROMPT,
    }),
    name: "human_in_the_loop",
    description: "AWS Strands agent with human-in-the-loop task planning",
  });
}

runIfMain(import.meta.url, async () => {
  // Port first: it throws on a malformed PORT, and building the agent first
  // would surface a missing API key instead and hide the real complaint.
  const port = demoPort();
  const app = await createStrandsApp(await createHumanInTheLoopAgent(), {
    path: "/",
  });
  listenOrExit(app, "human-in-the-loop", port);
});

aws-strands-typescript::interrupt.content:
"use client";
import React, { useMemo, useState } from "react";
import "@copilotkit/react-core/v2/styles.css";
import {
  CopilotChat,
  CopilotChatConfigurationProvider,
  useConfigureSuggestions,
  useInterrupt,
} from "@copilotkit/react-core/v2";
import { CopilotKit } from "@copilotkit/react-core";
import { useTheme } from "next-themes";

interface InterruptProps {
  params: Promise<{ integrationId: string }>;
}

// Payload the Mastra `schedule_meeting` tool sends via `suspend(...)`. The
// @ag-ui/mastra bridge wraps it in the on_interrupt CUSTOM event under
// `suspendPayload` (the Mastra contract, which carries `toolName`/`toolCallId`/
// `runId` the LangGraph raw-value shape doesn't). We read `suspendPayload`.
interface SuspendPayload {
  topic?: string;
  attendee?: string;
}

interface TimeSlot {
  iso: string;
  label: string;
}

// Generate a few future slots relative to "now" so the picker is always valid.
function generateSlots(): TimeSlot[] {
  const slots: TimeSlot[] = [];
  const now = new Date();
  for (let day = 1; day <= 2; day++) {
    for (const hour of [10, 14]) {
      const d = new Date(now);
      d.setDate(now.getDate() + day);
      d.setHours(hour, 0, 0, 0);
      slots.push({
        iso: d.toISOString(),
        label: d.toLocaleString(undefined, {
          weekday: "short",
          month: "short",
          day: "numeric",
          hour: "numeric",
          minute: "2-digit",
        }),
      });
    }
  }
  return slots;
}

const Interrupt: React.FC<InterruptProps> = ({ params }) => {
  const { integrationId } = React.use(params);

  return (
    <CopilotKit
      runtimeUrl={`/api/copilotkit/${integrationId}`}
      showDevConsole={false}
      agent="interrupt"
    >
      <CopilotChatConfigurationProvider agentId="interrupt">
        <ChatContent />
      </CopilotChatConfigurationProvider>
    </CopilotKit>
  );
};

const ChatContent = () => {
  useConfigureSuggestions({
    suggestions: [
      {
        title: "Book a call with sales",
        message: "Book an intro call with the sales team to discuss pricing.",
      },
      {
        title: "Schedule a 1:1 with Alice",
        message: "Schedule a 1:1 with Alice next week to review Q2 goals.",
      },
    ],
    available: "always",
  });

  // Native interrupt handling. The agent pauses its `schedule_meeting` tool,
  // the bridge publishes that pause, this renders the picker, and
  // `resolve(...)` resumes the paused tool with the user's choice.
  useInterrupt({
    agentId: "interrupt",
    renderInChat: true,
    render: ({ event, resolve }) => {
      // The adapter JSON-stringifies the interrupt value, so parse it.
      const raw = event.value ?? {};
      const parsed = (typeof raw === "string" ? JSON.parse(raw) : raw) as {
        // Mastra suspends a tool and carries the payload under `suspendPayload`.
        suspendPayload?: SuspendPayload;
        metadata?: {
          // CrewAI suspends the FLOW, so the value is the AG-UI Interrupt shape
          // and the paused method's output sits under `metadata.crewai.output`.
          crewai?: { output?: SuspendPayload };
          // AWS Strands pauses inside the tool via the tool context's
          // `interrupt(reason=...)`, and the bridge publishes that argument
          // verbatim under `metadata.reason`.
          reason?: SuspendPayload;
        };
      };

      // Same picker every way: each framework pauses to ask for a meeting time,
      // and all of them take the same resume payload back through `resolve(...)`.
      const payload =
        parsed.suspendPayload ??
        parsed.metadata?.crewai?.output ??
        parsed.metadata?.reason ??
        {};
      return (
        <TimePickerCard
          topic={payload.topic ?? "a call"}
          attendee={payload.attendee}
          onPick={(slot) =>
            resolve({ chosen_time: slot.iso, chosen_label: slot.label })
          }
          onCancel={() => resolve({ cancelled: true })}
        />
      );
    },
  });

  return (
    <div className="flex justify-center items-center h-full w-full">
      <div className="h-full w-full md:w-8/10 md:h-8/10 rounded-lg">
        <CopilotChat
          agentId="interrupt"
          className="h-full rounded-2xl max-w-6xl mx-auto"
        />
      </div>
    </div>
  );
};

const TimePickerCard: React.FC<{
  topic: string;
  attendee?: string;
  onPick: (slot: TimeSlot) => void;
  onCancel: () => void;
}> = ({ topic, attendee, onPick, onCancel }) => {
  const { theme } = useTheme();
  const slots = useMemo(() => generateSlots(), []);
  const [done, setDone] = useState<TimeSlot | "cancelled" | null>(null);

  const dark = theme === "dark";

  // Once the user picks/cancels, render nothing: `resolve()` resumes the run and
  // this interrupt render unmounts moments later, with the agent's text taking
  // over as the confirmation. Blanking on click (rather than leaving the slots
  // up) gives an instant, clean handoff and prevents a double-pick. We don't
  // show a "Booked" card here, since it would only flash before unmounting; the
  // agent's message is the record.
  if (done) {
    return null;
  }

  return (
    <div
      data-testid="interrupt-picker"
      className={`rounded-xl w-[480px] p-6 shadow-lg ${
        dark
          ? "bg-slate-800 text-white border border-slate-700"
          : "bg-white text-gray-800 border border-gray-200"
      }`}
    >
      <h2 className="text-lg font-semibold mb-1">{topic}</h2>
      {attendee ? (
        <p className="text-sm opacity-70 mb-4">with {attendee}</p>
      ) : (
        <div className="mb-4" />
      )}

      <div className="grid grid-cols-2 gap-2">
        {slots.map((slot) => (
          <button
            key={slot.iso}
            type="button"
            data-testid={`interrupt-slot-${slot.iso}`}
            onClick={() => {
              setDone(slot);
              onPick(slot);
            }}
            className={`rounded-lg border px-3 py-3 text-sm font-medium transition-colors ${
              dark
                ? "border-slate-600 hover:border-blue-400 hover:bg-slate-700"
                : "border-gray-200 hover:border-blue-400 hover:bg-blue-50"
            }`}
          >
            {slot.label}
          </button>
        ))}
      </div>

      <button
        type="button"
        data-testid="interrupt-cancel"
        onClick={() => {
          setDone("cancelled");
          onCancel();
        }}
        className={`mt-4 w-full rounded-lg border px-3 py-2 text-xs font-medium uppercase tracking-wide transition-colors ${
          dark
            ? "border-slate-600 hover:bg-slate-700"
            : "border-gray-200 hover:bg-gray-50"
        }`}
      >
        Cancel
      </button>
    </div>
  );
};

export default Interrupt;

/**
 * Interrupt example for AWS Strands (TypeScript).
 *
 * Mirrors `python/examples/server/api/interrupt.py`.
 *
 * `schedule_meeting` pauses itself. Strands' native interrupt system lets a tool
 * call `context.interrupt(...)`, which halts the agent loop and finishes the run
 * with `RUN_FINISHED` carrying `outcome.type === "interrupt"`. The dojo's
 * interrupt page renders its time picker, and resuming on the same `threadId`
 * returns the user's choice from that same `interrupt()` call so the tool body
 * continues where it left off.
 *
 * The resume payload arrives wrapped: a resolved answer as `{ response: ... }`,
 * a client-side cancel as `{ cancelled: true }`. The adapter wraps it so one tool
 * body reads the same on both bridges, and because an answer the SDK reads as
 * absent would re-raise the same interrupt forever.
 *
 * Pause and resume happen on the same live wrapper and process here, so no
 * `SessionManager` is needed. Durable, cross-process resume requires one.
 */

import { Agent, tool } from "@strands-agents/sdk";
import { z } from "zod";
import { StrandsAgent } from "@ag-ui/aws-strands";
import { createStrandsApp } from "@ag-ui/aws-strands/server";
import { createModel } from "../model-factory";
import { demoPort, listenOrExit, runIfMain } from "../run-if-main";

/** What the picker sends back. */
interface MeetingChoice {
  chosen_time?: string;
  chosen_label?: string;
  cancelled?: boolean;
}

/** The envelope the adapter hands a resumed tool. */
interface ResumeEnvelope {
  /** `null` when the client answered with no payload at all. */
  response?: MeetingChoice | null;
  cancelled?: boolean;
}

const scheduleMeeting = tool({
  name: "schedule_meeting",
  description:
    "Ask the user to pick a meeting time, then confirm what was scheduled.",
  inputSchema: z.object({
    topic: z.string().describe("Short description of the meeting purpose."),
    attendee: z.string().optional().describe("Who the meeting is with."),
  }),
  callback: ({ topic, attendee }, context) => {
    // Typed optional by the SDK, so this is checked rather than asserted: with
    // no context there is nothing to pause on, and pretending otherwise would
    // schedule a meeting the user never saw.
    if (!context) {
      throw new Error("schedule_meeting needs a tool context to pause on");
    }

    // `attendee` is optional, and the reason has to be JSON, which has no
    // `undefined`. Omitted rather than sent as undefined so the picker sees the
    // field missing instead of present-and-empty.
    const answer = context.interrupt<ResumeEnvelope>({
      name: "schedule_meeting",
      reason: attendee === undefined ? { topic } : { topic, attendee },
    });

    // Two cancel shapes reach here: the adapter's sentinel for a cancelled
    // resume entry, and the picker's own Cancel button, which resolves with a
    // `cancelled` flag inside the payload.
    //
    // The answer is whatever the client sent, so it need not be an object at
    // all. Checked rather than assumed, and checked the same way the Python
    // example does: reading fields off a bare string or number silently yields
    // nothing here and raises there, which is the two demos disagreeing about
    // the same input.
    const inner = answer?.response;
    const payload: MeetingChoice =
      inner && typeof inner === "object" ? inner : {};
    if (answer?.cancelled || payload.cancelled) {
      return `User cancelled. Meeting NOT scheduled: ${topic}`;
    }

    const label = payload.chosen_label ?? payload.chosen_time;
    return label
      ? `Meeting scheduled for ${label}: ${topic}`
      : `User did not pick a time. Meeting NOT scheduled: ${topic}`;
  },
});

const SYSTEM_PROMPT = `You are a scheduling assistant.

Whenever the user asks you to book a call or schedule a meeting, you MUST call
the \`schedule_meeting\` tool. Pass a short \`topic\` describing the purpose and,
if known, an \`attendee\` describing who the meeting is with.

The tool pauses execution and shows the user a time picker. Once it resumes with
their choice, briefly confirm whether the meeting was scheduled and at what
time, or note that the user cancelled. Do not ask for approval yourself: always
call the tool and let the picker handle the decision. Keep responses short and
friendly.

Never claim a meeting is scheduled unless the tool result says so.`;

export async function createInterruptAgent(): Promise<StrandsAgent> {
  return new StrandsAgent({
    agent: new Agent({
      model: await createModel(),
      tools: [scheduleMeeting],
      systemPrompt: SYSTEM_PROMPT,
    }),
    name: "interrupt",
    description:
      "AWS Strands agent whose scheduling tool pauses for the user to pick a time",
  });
}

runIfMain(import.meta.url, async () => {
  // Port first: it throws on a malformed PORT, and building the agent first
  // would surface a missing API key instead and hide the real complaint.
  const port = demoPort();
  const app = await createStrandsApp(await createInterruptAgent(), {
    path: "/",
  });
  listenOrExit(app, "interrupt", port);
});

