namespace AGUIDojoServer;

/// <summary>
/// The managed agent behind each example route. <see cref="Provisioner"/> creates them;
/// <see cref="ExampleAgents"/> serves them. Add a route by adding an entry here.
/// </summary>
internal sealed class AgentSpec
{
    internal AgentSpec(string route, string agentName, string system)
    {
        Route = route;
        AgentName = agentName;
        System = system;
    }

    /// <summary>Route name and feature id.</summary>
    internal string Route { get; }

    /// <summary>Managed agent name (used to find or create it idempotently).</summary>
    internal string AgentName { get; }

    /// <summary>The agent's system prompt.</summary>
    internal string System { get; }

    /// <summary>The model the agents are created on. Override with <c>MANAGED_AGENTS_MODEL</c>.</summary>
    internal static string Model =>
        Environment.GetEnvironmentVariable("MANAGED_AGENTS_MODEL") is { Length: > 0 } model ? model : "claude-sonnet-5";

    /// <summary>The name of the environment the agents run in.</summary>
    internal const string EnvironmentName = "ag-ui-dojo";

    internal static IReadOnlyList<AgentSpec> All { get; } =
    [
        new AgentSpec(
            "agentic_chat",
            "ag-ui-dojo-agentic-chat",
            "You are a helpful assistant. Keep replies concise."),
        new AgentSpec(
            "backend_tool_rendering",
            "ag-ui-dojo-backend-tool-rendering",
            "You are a helpful assistant. When the user asks about the weather, call the " +
            "get_weather tool and then summarize the result in a sentence."),
        new AgentSpec(
            "human_in_the_loop",
            "ag-ui-dojo-human-in-the-loop",
            "You are a task planning assistant. For every request, IMMEDIATELY call the " +
            "generate_task_steps tool with about 10 steps, each an object with `description` " +
            "(brief imperative) and `status` set to \"enabled\". Do not repeat the steps as text; " +
            "the UI shows them. After the user approves steps via the tool result, confirm briefly."),
        new AgentSpec(
            "tool_based_generative_ui",
            "ag-ui-dojo-tool-based-generative-ui",
            "You are a haiku assistant. When asked, call the generate_haiku tool with the " +
            "haiku's lines in Japanese and English. Keep any other text short."),
    ];
}

using System.Text.Json;
using AGUI.ClaudeManagedAgents;

namespace AGUIDojoServer;

/// <summary>
/// Builds one <see cref="ManagedAgentsAgent"/> per example route from the provisioned IDs.
/// </summary>
internal static class ExampleAgents
{
    /// <summary>Server-executed tools per route.</summary>
    private static readonly IReadOnlyDictionary<string, IReadOnlyList<ManagedAgentsBackendTool>> s_backendTools =
        new Dictionary<string, IReadOnlyList<ManagedAgentsBackendTool>>
        {
            ["backend_tool_rendering"] = [GetWeather()],
        };

    /// <summary>
    /// Constructs the agents that have provisioned IDs, keyed by route. Missing configuration is
    /// logged and skipped so the server always starts.
    /// </summary>
    internal static Dictionary<string, ManagedAgentsAgent> Build()
    {
        var agents = new Dictionary<string, ManagedAgentsAgent>(StringComparer.Ordinal);
        var ids = ProvisionedIds.Load();
        if (ids is null)
        {
            Console.Error.WriteLine(
                $"No provisioned agents ({ProvisionedIds.FilePath} missing); run `dotnet run -- setup`. Serving no routes.");
            return agents;
        }

        if (string.IsNullOrEmpty(ids.EnvironmentId))
        {
            Console.Error.WriteLine(
                $"No environmentId in {ProvisionedIds.FilePath}; re-run setup. Serving no routes.");
            return agents;
        }

        foreach (var spec in AgentSpec.All)
        {
            if (!ids.Agents.TryGetValue(spec.Route, out var agentId) || string.IsNullOrEmpty(agentId))
            {
                Console.Error.WriteLine($"No agent provisioned for {spec.Route}; skipping. Re-run setup.");
                continue;
            }

            var options = new ManagedAgentsAgentOptions
            {
                ManagedAgentId = agentId,
                EnvironmentId = ids.EnvironmentId,
            };
            if (s_backendTools.TryGetValue(spec.Route, out var tools))
            {
                foreach (var tool in tools)
                {
                    options.BackendTools.Add(tool);
                }
            }

            agents[spec.Route] = new ManagedAgentsAgent(options);
        }

        return agents;
    }

    private static ManagedAgentsBackendTool GetWeather()
    {
        return new ManagedAgentsBackendTool
        {
            Name = "get_weather",
            Description = "Get the current weather for a location.",
            Parameters = JsonSerializer.SerializeToElement(new
            {
                type = "object",
                properties = new
                {
                    location = new { type = "string", description = "City name" },
                },
                required = new[] { "location" },
            }),
            Handler = input =>
            {
                var location = input.ValueKind == JsonValueKind.Object
                    && input.TryGetProperty("location", out var value)
                    && value.ValueKind == JsonValueKind.String
                        ? value.GetString() ?? "somewhere"
                        : "somewhere";
                var weather = new
                {
                    location,
                    temperature = 21,
                    conditions = "sunny",
                    humidity = 48,
                    windSpeed = 12,
                };
                return Task.FromResult(JsonSerializer.Serialize(weather));
            },
        };
    }
}

/// <summary>
/// Example server: one AG-UI endpoint per route, each backed by a managed agent.
/// Provision the agents first with `dotnet run -- setup`.
/// </summary>
///
/// <example>
/// ANTHROPIC_API_KEY=sk-ant-xxx dotnet run -- setup   # provision the environment and agents
/// ANTHROPIC_API_KEY=sk-ant-xxx dotnet run            # serve on http://localhost:8026
/// </example>

using AGUIDojoServer;

if (args.Length > 0 && string.Equals(args[0], "setup", StringComparison.Ordinal))
{
    if (!HasApiKey())
    {
        Console.Error.WriteLine("Error: set ANTHROPIC_API_KEY (or ANTHROPIC_AUTH_TOKEN)");
        return 1;
    }

    await Provisioner.RunAsync();
    return 0;
}

var builder = WebApplication.CreateBuilder(args);
// PORT is what the README and the Dockerfile advertise; honour it here as well so
// `PORT=9000 dotnet run` listens where it says it does rather than only inside the
// container, whose entrypoint sets ASPNETCORE_URLS from it. An explicit --urls (or
// ASPNETCORE_URLS) still wins.
var port = Environment.GetEnvironmentVariable("PORT");
var defaultUrl = string.IsNullOrWhiteSpace(port) ? "http://0.0.0.0:8026" : $"http://0.0.0.0:{port}";
builder.WebHost.UseUrls(builder.Configuration["urls"] ?? defaultUrl);
builder.Services.AddCors(options => options.AddDefaultPolicy(policy =>
    policy.AllowAnyOrigin().AllowAnyHeader().WithMethods("GET", "POST", "OPTIONS")));

var app = builder.Build();
app.UseCors();

if (!HasApiKey())
{
    Console.Error.WriteLine("Warning: ANTHROPIC_API_KEY (or ANTHROPIC_AUTH_TOKEN) is not set; runs will fail.");
}

var agents = ExampleAgents.Build();
foreach (var (route, agent) in agents)
{
    app.MapManagedAgentsAgent($"/{route}", agent);
}

app.MapGet("/health", () => Results.Json(new { status = "healthy", agents = agents.Keys }));

app.Lifetime.ApplicationStarted.Register(() =>
{
    Console.WriteLine("Claude Managed Agents example server");
    foreach (var url in app.Urls)
    {
        foreach (var route in agents.Keys)
        {
            Console.WriteLine($"  POST {url}/{route}");
        }

        Console.WriteLine($"  GET  {url}/health");
    }
});

await app.RunAsync();
return 0;

static bool HasApiKey()
{
    return !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("ANTHROPIC_API_KEY"))
        || !string.IsNullOrEmpty(Environment.GetEnvironmentVariable("ANTHROPIC_AUTH_TOKEN"));
}

