    location = (
        tool_input.get("location", "somewhere")
        if isinstance(tool_input, dict)
        else "somewhere"
    )
    return json.dumps(
        {
            "location": location,
            "temperature": 21,
            "conditions": "sunny",
            "humidity": 48,
            "windSpeed": 12,
